import { growthHubStyles } from "@v3/sales/components/sales/growth-hub-styles";
import { Link, useNavigate } from "@tanstack/react-router";
import { useMemo, useState } from "react";
import { useMutation, useQuery } from "@tanstack/react-query";
import { ArrowLeft, ArrowRight, CalendarPlus, Check, CheckCircle2, Circle, Clock3, Crown, ExternalLink, FilePlus2, Mail, MessageSquarePlus, Pencil, PhoneCall, Pin, PinOff, Plus, Trophy, UserPlus, XCircle } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@v3/ui/components/ui/button";
import { Checkbox } from "@v3/ui/components/ui/checkbox";
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "@v3/ui/components/ui/dialog";
import { Input } from "@v3/ui/components/ui/input";
import { Label } from "@v3/ui/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@v3/ui/components/ui/select";
import { Textarea } from "@v3/ui/components/ui/textarea";
import { EmptyState, Panel } from "@v3/ui/components/console/primitives";
import { AvatarStack, BrandAvatar } from "@v3/ui/components/sales/entity-avatar";
import { addContact, addOppNote, addOppTask, advanceStage, closeOpportunityLost, closeOpportunityWon, completeOpportunityDemo, contactName, convertNoteToTask, loadStageRequirements, logOpportunityActivity, nextStage, setTaskDone, updateOpportunityContact, updateOppNote, usd, type OpportunityFile, type OppContact, type OppFile, type StageField } from "@v3/sales/lib/opportunity-file";
import { cn } from "@v3/ui/lib/utils";
import { prepareOpportunityQuote } from "@v3/sales/lib/sales-cpq";
import { buildTimeline, missingRequired, type TimelineItem } from "@v3/sales/lib/crm-lifecycle";
import { useServerFn } from "@v3/ui/lib/server-fn";
import { scheduleOpportunityMeeting } from "@v3/ui/lib/google-workspace.functions";
import { AlertsFeed, AuditPanel, EmailDialog, useGoogleDelivery } from "@v3/sales/components/sales/opportunity-automation";

const MODULE_STAGES = ["qualification", "discovery", "design", "demo", "buy_in", "proposal"];
const COMMITTEE_ROLES = ["Economic Buyer", "Champion", "Decision Maker", "Influencer", "User", "Blocker", "Procurement/Legal"];
type ActionKind = "call" | "email" | "note" | "demo" | "meeting" | "reminder" | `demo-complete:${string}` | null;
type TimelineCategory = "All" | TimelineItem["category"];
const dt = (value: string | null | undefined) => value ? new Date(value).toLocaleString("en-US", { dateStyle: "medium", timeStyle: "short" }) : "—";
const dayCount = (value: string | null | undefined) => value ? Math.max(0, Math.floor((Date.now() - Date.parse(value)) / 86_400_000)) : null;

export function OpportunityWorkspace({ data, onRefresh }: { data: OpportunityFile; onRefresh: () => void }) {
  const { opp, account, brand, ownerName, contacts, products, events, claimEvents, history, meetings, team, notes, tasks } = data;
  const stages = data.stages.filter((stage) => MODULE_STAGES.includes(stage.key)).sort((a, b) => a.sort - b.sort);
  const current = stages.find((stage) => stage.key === opp.stage) ?? null;
  const next = nextStage(stages, opp.stage);
  const [selectedKey, setSelectedKey] = useState(current?.key ?? stages[0]?.key ?? "qualification");
  const gateStage = selectedKey === current?.key && next ? next : stages.find((stage) => stage.key === selectedKey) ?? current;
  const gate = useQuery({ queryKey: ["stage-requirements", gateStage?.key], queryFn: () => loadStageRequirements(gateStage?.key ?? ""), enabled: !!gateStage });
  const [answers, setAnswers] = useState<Record<string, unknown>>({});
  const [closeKind, setCloseKind] = useState<"lost" | "won" | null>(null);
  const [action, setAction] = useState<ActionKind>(null);
  const [editingNoteId, setEditingNoteId] = useState<string | null>(null);
  const [editingContactId, setEditingContactId] = useState<string | null>(null);
  const [timelineFilter, setTimelineFilter] = useState<TimelineCategory>("All");
  const [drillMetric, setDrillMetric] = useState<string | null>(null);
  const [composeOpen, setComposeOpen] = useState(false);
  const navigate = useNavigate();
  const completedDemo = meetings.some((meeting) => meeting.attended && !!meeting.outcome?.trim());
  const effectiveAnswers = useMemo(() => gateStage?.key === "demo" && completedDemo ? { ...answers, "Demo delivered": true } : answers, [answers, completedDemo, gateStage?.key]);
  const requiredMissing = useMemo(() => missingRequired(gate.data ?? [], effectiveAnswers), [gate.data, effectiveAnswers]);
  const currentIndex = current ? stages.findIndex((stage) => stage.key === current.key) : -1;
  const latestMove = history.find((move) => move.to_stage === opp.stage)?.moved_at ?? opp.created_at;
  const days = dayCount(latestMove);
  const timelineItems = useMemo(() => buildTimeline(data), [data]);
  const filteredTimeline = timelineFilter === "All" ? timelineItems : timelineItems.filter((item) => item.category === timelineFilter);
  const nextMeeting = meetings.find((meeting) => meeting.booked_at && Date.parse(meeting.booked_at) >= Date.now()) ?? null;
  const currentArr = account?.active_arr ?? null;
  const expectedArr = opp.value;
  const productTotal = products.length ? products.reduce((sum, row) => sum + Number(row.amount ?? 0), 0) : null;
  const expansion = productTotal == null ? null : Math.max(0, productTotal - Number(currentArr ?? 0));
  const closed = opp.stage === "won" || opp.stage === "lost";
  const atRisk = !closed && !tasks.some((task) => !task.done);
  const pinnedNotes = notes.filter((note) => note.pinned);
  const intel = data.intelligence;

  const advance = useMutation({
    mutationFn: () => {
      if (!next || gateStage?.key !== next.key) throw new Error("Select the next stage to advance");
      return advanceStage({ opportunityId: opp.id, toStage: next.key, captured: effectiveAnswers });
    },
    onSuccess: () => { toast.success(`Advanced to ${next?.label ?? "next stage"}`); setAnswers({}); onRefresh(); },
    onError: (error: Error) => toast.error(error.message),
  });

  const createQuote = useMutation({
    mutationFn: async () => {
      if (!intel) throw new Error("Logo intelligence is unavailable for this opportunity");
      if (opp.stage !== "proposal") {
        if (next?.key !== "proposal" || gateStage?.key !== "proposal") throw new Error("Advance through the configured stages before creating a quote");
        if (requiredMissing.length) throw new Error(`Missing required evidence for Proposal: ${requiredMissing.join(", ")}`);
        await advanceStage({ opportunityId: opp.id, toStage: "proposal", captured: effectiveAnswers });
      }
      if (data.quoteId) return { quoteId: data.quoteId, created: false };
      return prepareOpportunityQuote({ opportunityId: opp.id, accountId: opp.account_id, accountOrgId: account?.org_id ?? opp.org_id, accountName: account?.name ?? brand?.name ?? opp.name, professionalCount: intel.professionalCount, locationCount: intel.locationCount, productKeys: intel.products.filter((product) => product.likely && !product.owned).map((product) => product.key) });
    },
    onSuccess: (result) => { toast.success(result.created ? "Quote created in CPQ" : "Opening the linked quote"); void navigate({ to: "/sales/quotes/$quoteId", params: { quoteId: result.quoteId } }); },
    onError: (error: Error) => toast.error(error.message),
  });

  return <div className="opp-workspace"><style>{WORKSPACE_CSS + growthHubStyles(".opp-workspace") + OPPORTUNITY_POLISH}</style>
    <header className="command-header">
      <div className="command-top">
        <div className="brand-title">
          <BrandAvatar name={brand?.name ?? opp.name} logoUrl={brand?.logo_url} size="lg" />
          <div><p className="eyebrow">Opportunity · auto-named from logo</p><h1>{brand?.name ?? opp.name}</h1><p className="subline">{brand?.gcid?.replace("gcid:", "").replaceAll("_", " ") ?? "Category —"} · {brand?.locations == null ? "— locations" : `${brand.locations.toLocaleString()} locations`} · {opp.source_channel ?? "Source —"} → {ownerName ?? "Owner —"}</p></div>
        </div>
        <div className="header-actions"><Button asChild variant="outline" size="sm"><Link to="/sales/opportunities"><ArrowLeft />Opportunities</Link></Button><AvatarStack people={team.map((rep) => ({ id: rep.id, name: rep.name, photoUrl: rep.photo_url }))} max={6}/></div>
      </div>
      {team.length ? <div className="deal-team">{team.map((rep) => <span key={rep.id}>{rep.is_nora ? <Crown /> : null}{rep.name}<b>{rep.lane_role ?? rep.role ?? "Team"}</b></span>)}</div> : <p className="muted-line">Deal team —</p>}
      <div className="metrics">
        <Metric label="Stage" value={current?.label ?? opp.stage} />
        <Metric label="Expected ARR" value={expectedArr == null ? "—" : usd(expectedArr)} note={opp.probability == null ? undefined : `${opp.probability}% probability`} />
        <Metric label="Current ARR" value={currentArr == null ? "—" : usd(currentArr)} />
        <Metric label="Expansion headroom" value={expansion == null ? "—" : usd(expansion)} />
        <Metric label="Days in stage" value={days == null ? "—" : String(days)} tone={days != null && days >= 21 ? "amber" : undefined} />
        <Metric label="Last activity" value={timelineItems[0] ? dt(timelineItems[0].occurredAt) : "—"} />
        <Metric label="Next meeting" value={nextMeeting ? dt(nextMeeting.booked_at) : "—"} />
      </div>
      <div className="quick-actions">
        <Button variant="outline" size="sm" onClick={() => setAction("call")}><PhoneCall/>Log call</Button><Button variant="outline" size="sm" onClick={() => setComposeOpen(true)}><Mail/>Send email</Button><Button variant="outline" size="sm" onClick={() => setAction("email")}><Mail/>Log email</Button><Button variant="outline" size="sm" onClick={() => setAction("note")}><MessageSquarePlus/>Note</Button><Button variant="outline" size="sm" onClick={() => setAction("meeting")}><CalendarPlus/>Schedule meeting</Button><Button variant="outline" size="sm" onClick={() => setAction("demo")}><CalendarPlus/>Book demo</Button><Button variant="outline" size="sm" onClick={() => setAction("reminder")}><Clock3/>Reminder</Button><Button variant="outline" size="sm" onClick={() => setEditingContactId("__new__")}><UserPlus/>Add contact</Button>{atRisk ? <span className="risk-badge"><Clock3/>At risk — no next step</span> : null}
      </div>
    </header>

    <nav className="stage-stepper" aria-label="Opportunity stages">
      {stages.map((stage, index) => { const complete = index < currentIndex; const active = stage.key === current?.key; const selected = stage.key === selectedKey; return <button key={stage.key} type="button" onClick={() => { setSelectedKey(stage.key); setAnswers({}); }} className={cn(complete && "complete", active && "active", selected && "selected")}><span>{complete ? <Check/> : index + 1}</span><b>{stage.label}</b></button>; })}
    </nav>

    <div className="workspace-grid">
      <section className="left-column">
        <Panel title={`${gateStage?.label ?? "Stage"} evidence gate`} description={gateStage?.key === next?.key ? `Required to advance from ${current?.label ?? opp.stage}.` : "Review this stage's configured evidence."}>
          {gate.isLoading ? <div className="skeleton"/> : (gate.data ?? []).length ? <div className="evidence-list">{(gate.data ?? []).map((field) => <EvidenceField key={field.id} field={field} value={answers[field.field_label]} onChange={(value) => setAnswers((previous) => ({ ...previous, [field.field_label]: value }))} contacts={contacts} files={data.files}/>)}</div> : <EmptyState title="No requirements configured" compact/>}
          {gateStage?.key === next?.key && next ? <div className="advance-box">{requiredMissing.length ? <p><XCircle/>Missing: {requiredMissing.join(", ")}</p> : <p className="ready"><CheckCircle2/>Required evidence captured</p>}<Button disabled={closed || requiredMissing.length > 0 || advance.isPending} onClick={() => advance.mutate()}>Advance to {next.label}<ArrowRight/></Button>{gateStage?.key === "demo" && completedDemo ? <p className="ready"><CheckCircle2/>Demo delivered</p> : null}</div> : null}
          {current?.key === "proposal" || next?.key === "proposal" ? <Button className="mt-4 w-full" disabled={createQuote.isPending || (current?.key !== "proposal" && requiredMissing.length > 0)} onClick={() => createQuote.mutate()}><FilePlus2/>{data.quoteId ? "Open Quote" : "Create Quote"}</Button> : null}
        </Panel>
        {!closed ? <div className="close-row"><Button variant="outline" onClick={() => setCloseKind("lost")}><XCircle/>Closed Lost</Button><Button variant="outline" onClick={() => setCloseKind("won")}><Trophy/>Closed Won</Button></div> : <div className={cn("closed-banner", opp.stage)}>{opp.stage === "won" ? "Closed Won · logo handed to Success" : "Closed Lost · logo remains in territory"}</div>}
      </section>

      <section className="center-column">
        {pinnedNotes.length ? <Panel title="Pinned notes" description="Important context kept above the activity stream."><div className="note-stack">{pinnedNotes.map((note) => <NoteCard key={note.id} note={note} onEdit={() => setEditingNoteId(note.id)} onRefresh={onRefresh} data={data}/>)}</div></Panel> : null}
        <Panel title="Activity timeline" description="Sales, product, claim, revenue, NORA, note, meeting, task and stage history."><div className="timeline-filters">{(["All","Sales","Product engagement","Claims","Revenue","NORA"] as TimelineCategory[]).map((filter) => <Button key={filter} size="sm" variant={timelineFilter === filter ? "default" : "outline"} onClick={() => setTimelineFilter(filter)}>{filter}</Button>)}</div><Timeline items={filteredTimeline}/></Panel>
        <Panel title="Notes" description="Pinned notes also stay at the top of this workspace.">{notes.length ? <div className="note-stack">{notes.map((note) => <NoteCard key={note.id} note={note} onEdit={() => setEditingNoteId(note.id)} onRefresh={onRefresh} data={data}/>)}</div> : <EmptyState title="No notes yet" compact/>}</Panel>
        <Panel title="Tasks & reminders" description="Every open opportunity should have a next step.">{tasks.length ? <ul className="task-list">{tasks.map((task) => <li key={task.id}><Checkbox checked={!!task.done} onCheckedChange={async (checked) => { try { await setTaskDone(opp.id, task.id, checked === true); toast.success(checked ? "Task completed" : "Task reopened"); onRefresh(); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to update task"); } }}/><div><b>{task.title ?? "Untitled task"}</b><span>{task.task_type ?? "task"} · {dt(task.due_at)} · {task.priority ?? "normal"}</span></div></li>)}</ul> : <EmptyState title="No tasks yet" compact/>}</Panel>
      </section>

      <aside className="right-column">
        <Panel title="Logo engagement" description="Live claim, commercial, and Search Rank signals.">
          {intel ? <><div className="engagement-grid">
            <EngagementTile label="Claims · 7d" value={String(intel.claims7d)} onClick={() => setDrillMetric("Claims · 7d")}/><EngagementTile label="Claims · 30d" value={String(intel.claims30d)} onClick={() => setDrillMetric("Claims · 30d")}/><EngagementTile label="Attempted" value={String(intel.attempted)} onClick={() => setDrillMetric("Attempted")}/><EngagementTile label="Warm-up" value={String(intel.warmUp)} onClick={() => setDrillMetric("Warm-up")}/><EngagementTile label="Outside warm-up" value={String(intel.outsideWarmUp)} onClick={() => setDrillMetric("Outside warm-up")}/><EngagementTile label="Upgraded" value={String(intel.upgraded)} onClick={() => setDrillMetric("Upgraded")}/><EngagementTile label="Current spend" value={usd(intel.currentArr)} onClick={() => setDrillMetric("Current spend")}/><EngagementTile label="Upgrade headroom" value={usd(intel.headroom)} onClick={() => setDrillMetric("Upgrade headroom")}/><EngagementTile label="Avg Search Rank" value={intel.averageScore == null ? "—" : intel.averageScore.toFixed(0)} onClick={intel.averageScore == null ? undefined : () => setDrillMetric("Avg Search Rank")}/><EngagementTile label="Active users" value="—" pending/><EngagementTile label="Recent logins" value="—" pending/><EngagementTile label="Product usage" value="—" pending/><EngagementTile label="Score over time" value="—" pending/>
          </div><p className="cluster-line">{intel.warmUp.toLocaleString()} warm-up · {intel.outsideWarmUp.toLocaleString()} outside · {intel.upgraded.toLocaleString()} upgraded · {usd(intel.currentArr)} current ARR · {usd(intel.headroom)} est. headroom</p>{drillMetric ? <ProfileDrill metric={drillMetric} profiles={intel.profiles} onClose={() => setDrillMetric(null)}/> : null}</> : <EmptyState title="No logo source attached" compact/>}
        </Panel>
        <Panel title="Buying committee" description="Contacts grouped by their role in this decision.">{contacts.length ? <div className="committee-groups">{COMMITTEE_ROLES.map((role) => { const people = contacts.filter((contact) => normalizedRole(contact) === role); return people.length ? <section key={role}><h3>{role}</h3><ul className="committee">{people.map((contact) => <li key={contact.link_id}><div><b>{contactName(contact)}</b><span>{contact.job_title ?? "—"} · {contact.source_origin === "claim" ? "From claim" : "Manual"}</span><small>Relationship {contact.relationship_strength ?? "—"}/5 · Last touch {dt(contact.last_touch_at)}</small></div><div>{contact.is_champion ? <em>Champion</em> : <Button size="sm" variant="outline" onClick={() => setEditingContactId(contact.link_id)}><Crown/>Mark champion</Button>}<Button size="icon" variant="ghost" aria-label={`Edit ${contactName(contact)}`} onClick={() => setEditingContactId(contact.link_id)}><Pencil/></Button></div></li>)}</ul></section> : null; })}</div> : <EmptyState title="No contacts yet" compact/>}</Panel>
        <Panel title="Meetings & demos" description="Booked sessions and completed outcomes.">{meetings.length ? <div className="meeting-list">{meetings.map((meeting) => <div key={meeting.id}><b>{dt(meeting.booked_at)}</b><span>{meeting.objective ?? "No objective"}</span>{meeting.attended && meeting.outcome ? <em>Demo delivered · {meeting.outcome}</em> : <Button size="sm" variant="outline" onClick={() => setAction(`demo-complete:${meeting.id}`)}>Add disposition</Button>}</div>)}</div> : <EmptyState title="No meetings booked" compact/>}</Panel>
        <Panel title="Products & whitespace" description="Ownership and likely products from the catalog; configuration stays in CPQ.">{intel?.products.length ? <><div className="arr-flow"><span>Current ARR<b>{usd(intel.currentArr)}</b></span><ArrowRight/><span>Potential ARR<b>{usd(intel.potentialArr)}</b></span><ArrowRight/><span>Expansion headroom<b>{usd(intel.headroom)}</b></span></div><ul className="products">{intel.products.map((product) => <li key={product.key}><span>{product.label}<small>{product.scopes.join(" · ") || "catalog"}</small></span><b className={product.owned ? "owned" : "whitespace"}>{product.owned ? "Owned" : product.likely ? "Whitespace · likely" : "Whitespace"}</b></li>)}</ul></> : <EmptyState title="No catalog products available" compact/>}</Panel>
        <AlertsFeed opportunityId={opp.id} onChanged={onRefresh}/>
        <AuditPanel data={data}/>
      </aside>
    </div>
    <EmailDialog key={`compose-${composeOpen}`} open={composeOpen} data={data} onClose={() => setComposeOpen(false)} onSaved={onRefresh}/>
    <CloseDialog kind={closeKind} opportunityId={opp.id} onClose={() => setCloseKind(null)} onSaved={onRefresh}/>
    <WorkspaceActionDialog key={`action-${action ?? "none"}`} kind={action} data={data} onClose={() => setAction(null)} onSaved={onRefresh}/>
    <NoteDialog key={`note-${editingNoteId ?? "none"}`} note={notes.find((note) => note.id === editingNoteId) ?? null} data={data} onClose={() => setEditingNoteId(null)} onSaved={onRefresh}/>
    <ContactDialog key={`contact-${editingContactId ?? "none"}`} open={editingContactId !== null} contact={contacts.find((contact) => contact.link_id === editingContactId) ?? null} data={data} onClose={() => setEditingContactId(null)} onSaved={onRefresh}/>
  </div>;
}

function Metric({ label, value, note, tone }: { label: string; value: string; note?: string; tone?: "amber" }) { return <div className={cn("metric gh-stat", tone)}><span>{label}</span><strong>{value}</strong>{note ? <small>{note}</small> : null}</div>; }
function EngagementTile({ label, value, pending, onClick }: { label: string; value: string; pending?: boolean; onClick?: () => void }) { const content = <><span>{label}</span><b>{value}</b>{pending ? <small>source pending</small> : <small>{onClick ? "view profiles" : "live source"}</small>}</>; return onClick ? <Button variant="outline" className="engagement-tile" onClick={onClick}>{content}</Button> : <div className="engagement-tile pending">{content}</div>; }
function ProfileDrill({ metric, profiles, onClose }: { metric: string; profiles: NonNullable<OpportunityFile["intelligence"]>["profiles"]; onClose: () => void }) { return <div className="profile-drill"><div><b>{metric} · underlying profiles</b><Button size="sm" variant="ghost" onClick={onClose}>Close</Button></div>{profiles.length ? <ul>{profiles.map((profile) => <li key={profile.id}><span>{profile.label}<small>{profile.eventType ?? "—"} · score {profile.score ?? "—"}</small></span><Button asChild size="icon" variant="ghost" aria-label={`Open ${profile.label}`}>{profile.type === "professional" ? <Link to="/sales/professionals/$proId" params={{ proId: profile.id }}><ExternalLink/></Link> : <Link to="/sales/locations/$orgId" params={{ orgId: profile.id }}><ExternalLink/></Link>}</Button></li>)}</ul> : <p>No underlying profiles for this metric.</p>}</div>; }

function EvidenceField({ field, value, onChange, contacts, files }: { field: StageField; value: unknown; onChange: (value: unknown) => void; contacts: OppContact[]; files: OppFile[] }) {
  const captured = field.field_type === "bool" ? value === true : Array.isArray(value) ? value.length > 0 : value != null && String(value).trim() !== "";
  const label = <div className="evidence-label"><span className={captured ? "captured" : "missing"}>{captured ? <Check/> : <Circle/>}</span><Label>{field.field_label}</Label><small>{field.required ? "Required" : "Optional"}</small></div>;
  if (field.field_type === "bool") return <label className="evidence-field checkbox-field">{label}<Checkbox checked={value === true} onCheckedChange={(checked) => onChange(checked === true)}/></label>;
  if (field.field_type === "contact") return <div className="evidence-field">{label}<Select value={typeof value === "string" ? value : ""} onValueChange={onChange}><SelectTrigger><SelectValue placeholder="Select contact"/></SelectTrigger><SelectContent>{contacts.map((contact) => <SelectItem key={contact.link_id} value={contactName(contact)}>{contactName(contact)}</SelectItem>)}</SelectContent></Select></div>;
  if (field.field_type === "file") return <div className="evidence-field">{label}<Select value={typeof value === "string" ? value : ""} onValueChange={onChange}><SelectTrigger><SelectValue placeholder="Select file"/></SelectTrigger><SelectContent>{files.map((file) => <SelectItem key={file.id} value={file.filename ?? file.id}>{file.filename ?? file.id}</SelectItem>)}</SelectContent></Select></div>;
  if (field.field_type === "multiselect") return <div className="evidence-field">{label}<Textarea rows={2} value={Array.isArray(value) ? value.join(", ") : ""} placeholder="Comma-separated" onChange={(event) => onChange(event.target.value.split(",").map((part) => part.trim()).filter(Boolean))}/></div>;
  return <div className="evidence-field">{label}<Input type={field.field_type === "number" ? "number" : field.field_type === "date" ? "date" : "text"} value={typeof value === "string" || typeof value === "number" ? value : ""} onChange={(event) => onChange(event.target.value)}/></div>;
}

function Timeline({ items }: { items: TimelineItem[] }) { return items.length ? <ol className="timeline">{items.map((item) => <li key={`${item.id}-${item.occurredAt}-${item.eventType}`}><span>{item.pinned ? <Pin/> : <CheckCircle2/>}</span><div><b>{item.eventType.replaceAll("_", " ")}</b>{item.detail ? <p>{item.detail}</p> : null}<p>{item.category} · {item.source ?? "manual"}{item.actor ? ` · ${item.actor}` : ""}</p><time>{dt(item.occurredAt)}</time></div></li>)}</ol> : <EmptyState title="No matching activity" description="No records match this filter." compact/>; }
function InfoRows({ rows }: { rows: [string, string][] }) { return <dl className="info-rows">{rows.map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl>; }

function normalizedRole(contact: OppContact) {
  const found = COMMITTEE_ROLES.find((role) => role.toLowerCase() === contact.role?.toLowerCase());
  if (found) return found;
  return contact.is_champion ? "Champion" : "User";
}

function parseMentions(value: string) { return [...new Set((value.match(/@[\w.-]+/g) ?? []).map((mention) => mention.slice(1)))]; }
function validRepId(value: string | null) { return value && /^[0-9a-f-]{36}$/i.test(value) ? value : null; }

function NoteCard({ note, data, onEdit, onRefresh }: { note: OpportunityFile["notes"][number]; data: OpportunityFile; onEdit: () => void; onRefresh: () => void }) {
  const [converting, setConverting] = useState(false);
  return <article className="note-card"><div><b>{note.pinned ? <Pin/> : null}{note.body ?? "Empty note"}</b><span>{dt(note.created_at)}{note.mentions?.length ? ` · ${note.mentions.map((mention) => `@${mention}`).join(" ")}` : ""}</span></div><div><Button size="icon" variant="ghost" aria-label="Edit note" onClick={onEdit}><Pencil/></Button><Button size="icon" variant="ghost" aria-label={note.pinned ? "Unpin note" : "Pin note"} onClick={async () => { try { await updateOppNote({ opportunityId: data.opp.id, noteId: note.id, body: note.body ?? "", pinned: !note.pinned, mentions: note.mentions ?? [] }); toast.success(note.pinned ? "Note unpinned" : "Note pinned"); onRefresh(); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to update note"); } }}>{note.pinned ? <PinOff/> : <Pin/>}</Button><Button size="sm" variant="outline" disabled={converting || !note.body} onClick={async () => { setConverting(true); try { await convertNoteToTask({ opportunityId: data.opp.id, accountId: data.opp.account_id, ownerId: validRepId(data.opp.owner), noteId: note.id, title: note.body ?? "Follow up", dueAt: null }); toast.success("Note converted to task"); onRefresh(); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to convert note"); } finally { setConverting(false); } }}>Convert to task</Button></div></article>;
}

function NoteDialog({ note, data, onClose, onSaved }: { note: OpportunityFile["notes"][number] | null; data: OpportunityFile; onClose: () => void; onSaved: () => void }) {
  const [body, setBody] = useState(note?.body ?? "");
  const [pinned, setPinned] = useState(!!note?.pinned);
  const save = useMutation({ mutationFn: () => updateOppNote({ opportunityId: data.opp.id, noteId: note?.id ?? "", body: body.trim(), pinned, mentions: parseMentions(body) }), onSuccess: () => { toast.success("Note updated"); onClose(); onSaved(); }, onError: (error: Error) => toast.error(error.message) });
  return <Dialog open={!!note} onOpenChange={(open) => { if (!open) onClose(); }}><DialogContent><DialogHeader><DialogTitle>Edit note</DialogTitle></DialogHeader><Textarea rows={6} value={body} onChange={(event) => setBody(event.target.value)} /><label className="check-row"><Checkbox checked={pinned} onCheckedChange={(checked) => setPinned(checked === true)}/>Pin note</label><p className="text-xs text-muted-foreground">Use @name to mention a teammate.</p><DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button disabled={!body.trim() || save.isPending} onClick={() => save.mutate()}>Save</Button></DialogFooter></DialogContent></Dialog>;
}

function WorkspaceActionDialog({ kind, data, onClose, onSaved }: { kind: ActionKind; data: OpportunityFile; onClose: () => void; onSaved: () => void }) {
  const [text, setText] = useState(""); const [secondary, setSecondary] = useState(""); const [attendees, setAttendees] = useState(""); const [date, setDate] = useState(""); const [priority, setPriority] = useState("normal");
  const isComplete = typeof kind === "string" && kind.startsWith("demo-complete:");
  const schedule = useServerFn(scheduleOpportunityMeeting); const delivery = useGoogleDelivery(); const [duration, setDuration] = useState("30");
  const isMeeting = kind === "demo" || kind === "meeting";
  const title = kind === "call" ? "Log call" : kind === "email" ? "Log email" : kind === "note" ? "Add note" : kind === "demo" ? "Book demo" : kind === "meeting" ? "Schedule meeting" : kind === "reminder" ? "Create reminder" : isComplete ? "Complete demo" : "";
  const save = useMutation({ mutationFn: async () => {
    if (kind === "call" || kind === "email") return logOpportunityActivity({ opportunityId: data.opp.id, accountId: data.opp.account_id, eventType: kind === "call" ? "call_logged" : "email_logged", actor: data.ownerName, value: { summary: text.trim() } });
    if (kind === "note") return addOppNote({ opportunityId: data.opp.id, subjectLabel: data.brand?.name ?? data.opp.name, sellerId: validRepId(data.opp.owner), body: text.trim(), pinned: false, mentions: parseMentions(text) });
    if (kind === "reminder") return addOppTask({ opportunityId: data.opp.id, accountId: data.opp.account_id, ownerId: validRepId(data.opp.owner), title: text.trim(), taskType: "reminder", dueAt: date || null, priority });
    if (isMeeting) { const r = await schedule({ data: { opportunityId: data.opp.id, kind: kind === "demo" ? "demo" : "meeting", start: new Date(date).toISOString(), durationMinutes: Math.max(15, Number(duration) || 30), objective: text.trim(), agenda: secondary.trim(), attendees: attendees.split(",").map((item) => item.trim()).filter(Boolean), sellerId: validRepId(data.opp.owner) } }); if (r.calendar === "pending") toast.message("Saved — calendar invite pending until Google is connected"); else if (r.calendar === "failed") toast.error("Saved, but the calendar invite failed; it stays pending for retry"); return; }
    if (isComplete && kind) return completeOpportunityDemo({ opportunityId: data.opp.id, demoId: kind.split(":")[1] ?? "", outcome: text.trim(), followUp: secondary.trim() || null, disposition: priority, recordingUrl: null });
  }, onSuccess: () => { toast.success(`${title} saved`); onClose(); onSaved(); }, onError: (error: Error) => toast.error(error.message) });
  const needsDate = isMeeting || kind === "reminder";
  return <Dialog open={!!kind} onOpenChange={(open) => { if (!open) onClose(); }}><DialogContent><DialogHeader><DialogTitle>{title}</DialogTitle></DialogHeader><div className="grid gap-3"><div><Label>{isMeeting ? "Objective" : isComplete ? "Outcome" : kind === "reminder" ? "Title" : "Summary"}</Label><Textarea value={text} onChange={(event) => setText(event.target.value)} /></div>{needsDate ? <div><Label>{isMeeting ? "Date and time" : "Due at"}</Label><Input type="datetime-local" value={date} onChange={(event) => setDate(event.target.value)}/></div> : null}{isMeeting ? <><p className="text-xs text-muted-foreground">{delivery.data?.canDeliver ? "A Google Calendar invite will be sent to attendees." : "Google Workspace is not connected — the meeting is saved and its calendar invite stays pending."}</p><div><Label>Duration (minutes)</Label><Input type="number" min="15" max="480" value={duration} onChange={(event) => setDuration(event.target.value)}/></div><div><Label>Agenda</Label><Textarea value={secondary} onChange={(event) => setSecondary(event.target.value)}/></div><div><Label>Attendees</Label><Input placeholder="Emails separated by commas" value={attendees} onChange={(event) => setAttendees(event.target.value)}/></div></> : null}{isComplete ? <><div><Label>Follow-up / next step</Label><Textarea value={secondary} onChange={(event) => setSecondary(event.target.value)}/></div><div><Label>Disposition</Label><Select value={priority} onValueChange={setPriority}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{["completed","follow_up","reschedule","no_show"].map((value) => <SelectItem key={value} value={value}>{value.replaceAll("_", " ")}</SelectItem>)}</SelectContent></Select></div></> : null}{kind === "reminder" ? <div><Label>Priority</Label><Select value={priority} onValueChange={setPriority}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{["low","normal","high","urgent"].map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></div> : null}</div><DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button disabled={!text.trim() || (isMeeting && !date) || save.isPending} onClick={() => save.mutate()}>Save</Button></DialogFooter></DialogContent></Dialog>;
}

function ContactDialog({ open, contact, data, onClose, onSaved }: { open: boolean; contact: OppContact | null; data: OpportunityFile; onClose: () => void; onSaved: () => void }) {
  const [firstName, setFirstName] = useState(""); const [lastName, setLastName] = useState(""); const [email, setEmail] = useState(""); const [phone, setPhone] = useState(""); const [jobTitle, setJobTitle] = useState(""); const [role, setRole] = useState(contact ? normalizedRole(contact) : "User"); const [strength, setStrength] = useState(String(contact?.relationship_strength ?? "")); const [lastTouch, setLastTouch] = useState(contact?.last_touch_at?.slice(0, 16) ?? ""); const detail = (contact?.champion_detail && typeof contact.champion_detail === "object" ? contact.champion_detail : {}) as Record<string, unknown>; const [why, setWhy] = useState(String(detail.why_they_care ?? "")); const [influence, setInfluence] = useState(String(detail.influence_level ?? "")); const [access, setAccess] = useState(String(detail.internal_access ?? "")); const [intro, setIntro] = useState(String(detail.willingness_to_intro ?? "")); const [nextIntro, setNextIntro] = useState(String(detail.next_requested_intro ?? ""));
  const championDetail = { why_they_care: why, influence_level: influence, internal_access: access, willingness_to_intro: intro, next_requested_intro: nextIntro };
  const save = useMutation({ mutationFn: () => contact ? updateOpportunityContact({ opportunityId: data.opp.id, linkId: contact.link_id, isChampion: true, relationshipStrength: strength ? Number(strength) : null, lastTouchAt: lastTouch || null, championDetail }) : addContact({ opportunityId: data.opp.id, accountId: data.opp.account_id, firstName, lastName, email: email || null, phone: phone || null, jobTitle: jobTitle || null, role, isChampion: role === "Champion", isPrimary: false, relationshipStrength: strength ? Number(strength) : null, lastTouchAt: lastTouch || null, championDetail: role === "Champion" ? championDetail : null }), onSuccess: () => { toast.success(contact ? "Champion details saved" : "Contact added"); onClose(); onSaved(); }, onError: (error: Error) => toast.error(error.message) });
  return <Dialog open={open} onOpenChange={(value) => { if (!value) onClose(); }}><DialogContent className="max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>{contact ? `Mark ${contactName(contact)} as champion` : "Add contact"}</DialogTitle></DialogHeader><div className="grid gap-3">{!contact ? <><div className="two-col"><div><Label>First name</Label><Input value={firstName} onChange={(event) => setFirstName(event.target.value)}/></div><div><Label>Last name</Label><Input value={lastName} onChange={(event) => setLastName(event.target.value)}/></div></div><div><Label>Email</Label><Input type="email" value={email} onChange={(event) => setEmail(event.target.value)}/></div><div><Label>Phone</Label><Input value={phone} onChange={(event) => setPhone(event.target.value)}/></div><div><Label>Job title</Label><Input value={jobTitle} onChange={(event) => setJobTitle(event.target.value)}/></div></> : null}<div><Label>Committee role</Label><Select value={role} onValueChange={setRole} disabled={!!contact}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{COMMITTEE_ROLES.map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></div><div><Label>Relationship strength (1–5)</Label><Input type="number" min="1" max="5" value={strength} onChange={(event) => setStrength(event.target.value)}/></div><div><Label>Last touch</Label><Input type="datetime-local" value={lastTouch} onChange={(event) => setLastTouch(event.target.value)}/></div>{contact || role === "Champion" ? <div className="champion-fields"><Label>Champion detail</Label><Textarea placeholder="Why they care" value={why} onChange={(event) => setWhy(event.target.value)}/><Input placeholder="Influence level" value={influence} onChange={(event) => setInfluence(event.target.value)}/><Input placeholder="Internal access" value={access} onChange={(event) => setAccess(event.target.value)}/><Input placeholder="Willingness to introduce" value={intro} onChange={(event) => setIntro(event.target.value)}/><Input placeholder="Next requested introduction" value={nextIntro} onChange={(event) => setNextIntro(event.target.value)}/></div> : null}</div><DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button disabled={save.isPending || (!contact && !firstName.trim() && !email.trim())} onClick={() => save.mutate()}>{contact ? "Mark champion" : "Add contact"}</Button></DialogFooter></DialogContent></Dialog>;
}

function CloseDialog({ kind, opportunityId, onClose, onSaved }: { kind: "lost" | "won" | null; opportunityId: string; onClose: () => void; onSaved: () => void }) {
  const [reason, setReason] = useState(""); const [competitor, setCompetitor] = useState(""); const [revisit, setRevisit] = useState("");
  const close = useMutation({ mutationFn: () => kind === "lost" ? closeOpportunityLost({ opportunityId, reason, competitor: competitor || null, revisit: revisit || null }) : closeOpportunityWon({ opportunityId, captured: {} }), onSuccess: () => { toast.success(kind === "lost" ? "Opportunity closed lost; logo remains in territory" : "Opportunity closed won; logo handed to Success"); onClose(); onSaved(); }, onError: (error: Error) => toast.error(error.message) });
  return <Dialog open={!!kind} onOpenChange={(open) => { if (!open) onClose(); }}><DialogContent><DialogHeader><DialogTitle>{kind === "lost" ? "Close opportunity as lost" : "Close opportunity as won"}</DialogTitle></DialogHeader>{kind === "lost" ? <div className="grid gap-3"><div><Label>Reason</Label><Textarea value={reason} onChange={(event) => setReason(event.target.value)}/></div><div><Label>Competitor</Label><Input value={competitor} onChange={(event) => setCompetitor(event.target.value)}/></div><div><Label>Revisit date</Label><Input type="date" value={revisit} onChange={(event) => setRevisit(event.target.value)}/></div><p className="text-xs text-muted-foreground">The logo stays in its territory.</p></div> : <p className="text-sm text-muted-foreground">Closed Won is the only action that hands the logo from new sales to Success.</p>}<DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button disabled={close.isPending || (kind === "lost" && !reason.trim())} onClick={() => close.mutate()}>{kind === "lost" ? "Close Lost" : "Close Won"}</Button></DialogFooter></DialogContent></Dialog>;
}

